import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as n,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Tencent Hunyuan glossary","description":"No how-to. Separate Hy, TokenHub, Yuanbao, and CodeBuddy, then the two cloud doc trees and three thinking vocabularies.","frontmatter":{"title":"Tencent Hunyuan glossary","description":"No how-to. Separate Hy, TokenHub, Yuanbao, and CodeBuddy, then the two cloud doc trees and three thinking vocabularies.","domain":"product","tags":["hunyuan","llm-api"],"role":"glossary"},"headers":[],"relativePath":"products/hunyuan/hunyuan-glossary.md","filePath":"products/hunyuan/hunyuan-glossary.md","lastUpdated":1787107158000}'),r={name:"products/hunyuan/hunyuan-glossary.md"};function d(s,e,l,i,h,u){return n(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="tencent-hunyuan-glossary" tabindex="-1">Tencent Hunyuan glossary <a class="header-anchor" href="#tencent-hunyuan-glossary" aria-label="Permalink to &quot;Tencent Hunyuan glossary&quot;">​</a></h1><p>No procedures. If you only need a door, use the <a href="./">learning map</a>.</p><h2 id="hy-hunyuan" tabindex="-1">Hy / Hunyuan <a class="header-anchor" href="#hy-hunyuan" aria-label="Permalink to &quot;Hy / Hunyuan&quot;">​</a></h2><p><strong>What it is:</strong> Tencent’s current brand for the self-developed model family. <a href="https://hunyuan.tencent.com/" target="_blank" rel="noreferrer">hunyuan.tencent.com</a> and <a href="https://hy.tencent.com/" target="_blank" rel="noreferrer">hy.tencent.com</a> are the same site. International copy has said “Tencent Hy, formerly known as Tencent Hunyuan”.</p><p><strong>What it is not:</strong> Yuanbao the app, a TokenHub account, or an executable.</p><p>Repos, papers, and the older cloud product still say Hunyuan. Both names must map to an official page. Do not invent a third product name like “Hunyuan 3.0” — the current flagship LM is <strong>Hy3</strong>.</p><p>Internals (why MoE, what MTP is) belong in <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a>.</p><h2 id="hy3" tabindex="-1">Hy3 <a class="header-anchor" href="#hy3" aria-label="Permalink to &quot;Hy3&quot;">​</a></h2><p><strong>What it is:</strong> Flagship language model shipped 2026-07-06. TokenHub slug <code>hy3</code>. Open weights at <a href="https://github.com/Tencent-Hunyuan/Hy3" target="_blank" rel="noreferrer">Tencent-Hunyuan/Hy3</a>: 295B total, 21B active, 256K context, Apache-2.0.</p><p>Hosted capabilities (<a href="https://cloud.tencent.com/document/product/1823/130051" target="_blank" rel="noreferrer">model list</a>): retained thinking, structured output, function calling, cache. The product page adds Coding / long-context / Agent.</p><p><strong>What it is not:</strong></p><ul><li>Not <code>hy3-preview</code> (official retire date 2026-08-31).</li><li>Not the image / video / 3D models.</li><li>Not a button inside CodeBuddy.</li></ul><h2 id="tokenhub" tabindex="-1">TokenHub <a class="header-anchor" href="#tokenhub" aria-label="Permalink to &quot;TokenHub&quot;">​</a></h2><p><strong>What it is:</strong> Tencent Cloud’s “LLM service platform”, product tree <strong>1823</strong>. Official overview: one door that <strong>bundles Hunyuan and third-party models</strong>. Calling Hy is one line of business.</p><p><strong>Why the name matters:</strong> In 2026 the Hy3 call guide, prices, keys, and Claude Code wiring all live on this tree. Calling it “the Hunyuan console” hides the multi-vendor catalog and collides with tree 1729.</p><p>Auth is a TokenHub API key, not a random CAM SecretId/SecretKey.</p><h2 id="two-cloud-doc-trees" tabindex="-1">Two cloud doc trees <a class="header-anchor" href="#two-cloud-doc-trees" aria-label="Permalink to &quot;Two cloud doc trees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tree</th><th>ID</th><th>How to use it now</th></tr></thead><tbody><tr><td>TokenHub</td><td>1823</td><td><strong>Primary source here.</strong> Hy3, prices, OpenAI-compatible endpoint</td></tr><tr><td>Tencent Hunyuan LLM</td><td>1729</td><td>Still online. Still shows older Hunyuan-T1 / TurboS specs</td></tr></tbody></table><p><a href="https://cloud.tencent.com/product/hunyuan" target="_blank" rel="noreferrer">cloud.tencent.com/product/hunyuan</a> still scrapes as the older lineup; <a href="https://cloud.tencent.com/product/tclm" target="_blank" rel="noreferrer">product/tclm</a> already features Hy3. When marketing pages disagree, <strong>TokenHub docs + hunyuan.tencent.com win</strong>, and the conflict is named in the prose.</p><h2 id="why-thinking-has-three-vocabularies" tabindex="-1">Why thinking has three vocabularies <a class="header-anchor" href="#why-thinking-has-three-vocabularies" aria-label="Permalink to &quot;Why thinking has three vocabularies&quot;">​</a></h2><p>Not three products — three official pages, three JSON shapes:</p><table tabindex="0"><thead><tr><th>Source</th><th>How it is spelled</th></tr></thead><tbody><tr><td>TokenHub call guide</td><td><code>thinking: { type: &quot;enabled&quot; }</code>; <code>reasoning_effort</code> (default <code>low</code> on <code>hy3</code>)</td></tr><tr><td>tclm product page</td><td><code>no_think</code> / <code>think_low</code> / <code>think_high</code></td></tr><tr><td>Hy3 open README</td><td><code>extra_body.chat_template_kwargs.reasoning_effort = no_think | low | high</code> (default <code>no_think</code>)</td></tr></tbody></table><p>This site does not guess that TokenHub <code>low</code> equals a particular open-weight enum. Copy the fields from the page you are actually calling. With <code>tools</code> present, TokenHub maps <code>low</code> to <code>high</code> (call guide).</p><h2 id="sibling-products-are-not-hunyuan" tabindex="-1">Sibling products are not Hunyuan <a class="header-anchor" href="#sibling-products-are-not-hunyuan" aria-label="Permalink to &quot;Sibling products are not Hunyuan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Official positioning</th><th>Entry</th><th>This site</th></tr></thead><tbody><tr><td>Yuanbao</td><td>“Tencent’s all-in-one AI assistant… already using the latest Hunyuan Hy3 model”</td><td><a href="https://yuanbao.tencent.com/" target="_blank" rel="noreferrer">yuanbao.tencent.com</a></td><td>#76</td></tr><tr><td>CodeBuddy</td><td>Tencent Cloud coding assistant (IDE / CLI)</td><td><a href="https://www.codebuddy.cn/" target="_blank" rel="noreferrer">codebuddy.cn</a></td><td>#78</td></tr><tr><td>WorkBuddy</td><td>Office agent workbench</td><td><a href="https://www.workbuddy.cn/" target="_blank" rel="noreferrer">workbuddy.cn</a></td><td>Map row</td></tr><tr><td>ima</td><td>“AI knowledge steward based on a knowledge base”</td><td><a href="https://ima.qq.com/" target="_blank" rel="noreferrer">ima.qq.com</a></td><td>Map row</td></tr></tbody></table><p>They <strong>consume</strong> Hunyuan (or other models). They are not “Hunyuan open capabilities”. The Hy3 README names CodeBuddy / Cline / KiloCode as evaluation scaffolds. That does not make Hunyuan equal to CodeBuddy.</p><h2 id="open-source-names-vs-api-slugs" tabindex="-1">Open-source names vs API slugs <a class="header-anchor" href="#open-source-names-vs-api-slugs" aria-label="Permalink to &quot;Open-source names vs API slugs&quot;">​</a></h2><p>The <a href="https://github.com/Tencent-Hunyuan" target="_blank" rel="noreferrer">Tencent-Hunyuan</a> org still uses Hunyuan* repo names (HunyuanVideo, HunyuanImage-3.0, Hunyuan3D-2.1). TokenHub call parameters prefer <code>hy-*</code> / <code>hy3</code>.</p><p>Reconcile against the page you are reading. Do not treat similar names as the same <code>model</code> field.</p><h2 id="internals-this-handbook-will-not-teach" tabindex="-1">Internals this handbook will not teach <a class="header-anchor" href="#internals-this-handbook-will-not-teach" aria-label="Permalink to &quot;Internals this handbook will not teach&quot;">​</a></h2><p>MoE routing, MTP speculative decoding, quantization training, RL post-training: the README has sections; they are model internals. Use <a href="./../../tech/fundamentals/LLM.html">LLM fundamentals</a>. This handbook only keeps official <strong>spec numbers and serve commands</strong>.</p>',31)])])}const m=t(r,[["render",d]]);export{b as __pageData,m as default};
